r, EditingElementStyle = editor }); _grid.Columns.Add(new DataGridTextColumn { Header = "字符串期望值", Binding = new Binding("ExpectedText") { Mode = BindingMode.TwoWay, UpdateSourceTrigger = UpdateSourceTrigger.PropertyChanged }, Width = 120, ElementStyle = left, EditingElementStyle = editor }); DataGridTextColumn writeColumn = new DataGridTextColumn { Header = "写入值（可编辑）", Binding = new Binding("ValueText") { Mode = BindingMode.TwoWay, UpdateSourceTrigger = UpdateSourceTrigger.PropertyChanged }, Width = 135, ElementStyle = center, EditingElementStyle = editor, Visibility = _writeMode ? Visibility.Visible : Visibility.Collapsed }; _grid.Columns.Add(writeColumn); _grid.Columns.Add(new DataGridTextColumn { Header = "说明", Binding = new Binding("Comment"), Width = new DataGridLength(1, DataGridLengthUnitType.Star), IsReadOnly = true, ElementStyle = left }); _view = new ListCollectionView(_rows); _view.Filter = FilterRow; _grid.ItemsSource = _view; ContextMenu menu = new ContextMenu(); menu.Items.Add(Menu("复制选中的信号名", (s, e) => CopySignalNames())); menu.Items.Add(Menu("复制所选单元格", (s, e) => ApplicationCommands.Copy.Execute(null, _grid))); menu.Items.Add(Menu("复制全部表格", (s, e) => CopyAll())); menu.Items.Add(new Separator()); menu.Items.Add(Menu("勾选全部信号", (s, e) => SetAll(true), !_singleMode)); menu.Items.Add(Menu("反选信号", (s, e) => Invert(), !_singleMode)); menu.Items.Add(Menu("清空信号选择", (s, e) => SetAll(false))); _grid.ContextMenu = menu; Grid.SetRow(_grid, 2); body.Children.Add(_grid); Grid.SetRow(body, 1); root.Children.Add(body);
