        private ToggleButton FilterButton(string text) { ToggleButton button = new ToggleButton { Content = text, MinWidth = 92, Height = 34, Style = SegmentStyle(), Margin = new Thickness(0), Cursor = Cursors.Hand }; button.Click += (s, e) => { _filter = text; if (_allFilter != null) _allFilter.IsChecked = ReferenceEquals(button, _allFilter); if (_selectedFilter != null) _selectedFilter.IsChecked = ReferenceEquals(button, _selectedFilter); if (_judgedFilter != null) _judgedFilter.IsChecked = ReferenceEquals(button, _judgedFilter); _view.Refresh(); }; return button; }
        private bool FilterRow(object value) { LocatorSignalRow row = value as LocatorSignalRow; if (row == null) return false; string search = _search.Text == "搜索信号名称" ? string.Empty : (_search.Text ?? string.Empty).Trim(); bool matches = search.Length == 0 || (row.Name + " " + row.OffsetText + " " + row.DataType + " " + row.Comment).IndexOf(search, StringComparison.OrdinalIgnoreCase) >= 0; return matches && (_filter == "全部" || _filter == "已选" && row.Use || _filter == "有判断" && row.Use && row.NeedsJudgment); }
        private void RowChanged(object sender, PropertyChangedEventArgs e) { LocatorSignalRow row = sender as LocatorSignalRow; if (_singleMode && !_guard && e.PropertyName == "Use" && row != null && row.Use) { _guard = true; foreach (LocatorSignalRow other in _rows.Where(value => value != row && value.Use)) other.Use = false; _guard = false; } RefreshFooter(); if (_filter != "全部") _view.Refresh(); }
        private void SetAll(bool selected) { if (_singleMode && selected) { LocatorSignalRow row = _rows.FirstOrDefault(); if (row != null) row.Use = true; return; } foreach (LocatorSignalRow row in _rows) row.Use = selected; }
        private void Invert() { if (_singleMode) return; foreach (LocatorSignalRow row in _rows) row.Use = !row.Use; }
        private void SetCheckedMode(string mode) { List<LocatorSignalRow> rows = _rows.Where(value => value.Use).ToList(); if (rows.Count == 0) { MessageBox.Show(this, "请先勾选信号。", "批量结果类型", MessageBoxButton.OK, MessageBoxImage.Information); return; } foreach (LocatorSignalRow row in rows) row.ResultMode = mode; }
        private void CopySignalNames() { List<LocatorSignalRow> rows = _rows.Where(value => value.Use).ToList(); if (rows.Count == 0) rows = _grid.SelectedItems.Cast<object>().OfType<LocatorSignalRow>().ToList(); if (rows.Count == 0) { MessageBox.Show(this, "请先勾选或选中信号。", "复制信号名", MessageBoxButton.OK, MessageBoxImage.Information); return; } Clipboard.SetText(string.Join(Environment.NewLine, rows.Select(value => value.Name))); }
        private void CopyAll() { StringBuilder text = new StringBuilder(); text.AppendLine("使用\t信号\tOffset\t类型\t结果类型\t下限\t上限\t比较\t单位\t字符串期望值\t写入值\t说明"); foreach (LocatorSignalRow row in _rows) text.AppendLine(string.Join("\t", new[] { row.Use ? "1" : "0", row.Name, row.OffsetText, row.DataType, row.ResultMode, row.LowLimitText, row.HighLimitText, row.CompareText, row.UnitText, row.ExpectedText, row.ValueText, (row.Comment ?? string.Empty).Replace("\t", " ").Replace("\r", " ").Replace("\n", " ") })); Clipboard.SetText(text.ToString()); }
        private void RefreshFooter() { int selected = _rows.Count(value => value.Use), judged = _rows.Count(value => value.Use && value.NeedsJudgment); _footer.Text = "已选 " + selected + " 项  ·  " + judged + " 项判断" + (_singleMode ? "  ·  单信号模式" : string.Empty); }
        private void Apply(object sender, RoutedEventArgs e) { _grid.CommitEdit(DataGridEditingUnit.Cell, true); _grid.CommitEdit(DataGridEditingUnit.Row, true); List<LocatorSignalRow> selected = _rows.Where(value => value.Use).ToList(); if (selected.Count == 0) { MessageBox.Show(this, "请至少选择一个信号。", "信号与判定配置", MessageBoxButton.OK, MessageBoxImage.Information); return; } if (_singleMode && selected.Count != 1) { MessageBox.Show(this, "单信号操作只能选择一个信号。", "信号与判定配置", MessageBoxButton.OK, MessageBoxImage.Information); return; } if (_writeMode && selected.Any(value => string.IsNullOrWhiteSpace(value.ValueText))) { MessageBox.Show(this, "已选择的写入信号必须填写写入值。", "信号与判定配置", MessageBoxButton.OK, MessageBoxImage.Information); return; } foreach (LocatorSignalRow edit in _rows) { LocatorSignalRow original = _sourceRows.FirstOrDefault(value => ReferenceEquals(value.Signal, edit.Signal) || value.Offset == edit.Offset && value.Name == edit.Name); if (original != null) original.CopyConfigurationFrom(edit); } DialogResult = true; }
        private void GridPreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e) { DependencyObject source = e.OriginalSource as DependencyObject; if (FindAncestor<CheckBox>(source) != null || FindAncestor<TextBox>(source) != null || FindAncestor<ComboBox>(source) != null) return; DataGridCell cell = FindAncestor<DataGridCell>(source); if (cell == null || cell.IsReadOnly || cell.IsEditing) return; cell.Focus(); _grid.CurrentCell = new DataGridCellInfo(cell); _grid.BeginEdit(); Dispatcher.BeginInvoke(new Action(() => { ComboBox combo = FindDescendant<ComboBox>(cell); if (combo != null) combo.IsDropDownOpen = true; })); }
        private static T FindAncestor<T>(DependencyObject value) where T : DependencyObject { while (value != null) { T match = value as T; if (match != null) return match; value = VisualTreeHelper.GetParent(value); } return null; }
        private static T FindDescendant<T>(DependencyObject value) where T : DependencyObject { if (value == null) return null; for (int index = 0; index < VisualTreeHelper.GetChildrenCount(value); index++) { DependencyObject child = VisualTreeHelper.GetChild(value, index); T match = child as T ?? FindDescendant<T>(child); if (match != null) return match; } return null; }
