        private static Style TableRowStyle() { Style style = new Style(typeof(DataGridRow)); style.Setters.Add(new Setter(Control.BackgroundProperty, Brushes.White)); style.Setters.Add(new Setter(Control.BorderBrushProperty, Brushes.Transparent)); style.Setters.Add(new Setter(Control.BorderThicknessProperty, new Thickness(3, 0, 0, 0))); Trigger selected = new Trigger { Property = DataGridRow.IsSelectedProperty, Value = true }; selected.Setters.Add(new Setter(Control.BackgroundProperty, new SolidColorBrush(Color.FromRgb(235, 244, 255)))); selected.Setters.Add(new Setter(Control.BorderBrushProperty, new SolidColorBrush(Color.FromRgb(24, 112, 224)))); style.Triggers.Add(selected); return style; }
        private static Style SegmentStyle() { Style style = new Style(typeof(ToggleButton)); style.Setters.Add(new Setter(Control.BackgroundProperty, Brushes.White)); style.Setters.Add(new Setter(Control.ForegroundProperty, Text(52, 67, 88))); style.Setters.Add(new Setter(Control.BorderBrushProperty, BorderColor())); style.Setters.Add(new Setter(Control.BorderThicknessProperty, new Thickness(1))); FrameworkElementFactory border = new FrameworkElementFactory(typeof(System.Windows.Controls.Border)); border.SetBinding(System.Windows.Controls.Border.BackgroundProperty, new Binding("Background") { RelativeSource = new RelativeSource(RelativeSourceMode.TemplatedParent) }); border.SetBinding(System.Windows.Controls.Border.BorderBrushProperty, new Binding("BorderBrush") { RelativeSource = new RelativeSource(RelativeSourceMode.TemplatedParent) }); border.SetBinding(System.Windows.Controls.Border.BorderThicknessProperty, new Binding("BorderThickness") { RelativeSource = new RelativeSource(RelativeSourceMode.TemplatedParent) }); FrameworkElementFactory content = new FrameworkElementFactory(typeof(ContentPresenter)); content.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Center); content.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center); content.SetBinding(ContentPresenter.ContentProperty, new Binding("Content") { RelativeSource = new RelativeSource(RelativeSourceMode.TemplatedParent) }); border.AppendChild(content); style.Setters.Add(new Setter(Control.TemplateProperty, new ControlTemplate(typeof(ToggleButton)) { VisualTree = border })); Trigger selected = new Trigger { Property = ToggleButton.IsCheckedProperty, Value = true }; selected.Setters.Add(new Setter(Control.BackgroundProperty, new SolidColorBrush(Color.FromRgb(24, 112, 224)))); selected.Setters.Add(new Setter(Control.ForegroundProperty, Brushes.White)); selected.Setters.Add(new Setter(Control.BorderBrushProperty, new SolidColorBrush(Color.FromRgb(24, 112, 224)))); style.Triggers.Add(selected); return style; }
        private static Style BlueCheckStyle() { Style style = new Style(typeof(CheckBox)); FrameworkElementFactory root = new FrameworkElementFactory(typeof(System.Windows.Controls.Border)); root.Name = "CheckBoxSquare"; root.SetValue(FrameworkElement.WidthProperty, 16d); root.SetValue(FrameworkElement.HeightProperty, 16d); root.SetValue(System.Windows.Controls.Border.BorderBrushProperty, new SolidColorBrush(Color.FromRgb(139, 151, 168))); root.SetValue(System.Windows.Controls.Border.BorderThicknessProperty, new Thickness(1)); FrameworkElementFactory mark = new FrameworkElementFactory(typeof(TextBlock)); mark.Name = "CheckMark"; mark.SetValue(TextBlock.TextProperty, "✓"); mark.SetValue(TextBlock.ForegroundProperty, Brushes.White); mark.SetValue(TextBlock.FontSizeProperty, 12d); mark.SetValue(TextBlock.FontWeightProperty, FontWeights.Bold); mark.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Center); mark.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center); mark.SetValue(UIElement.VisibilityProperty, Visibility.Collapsed); root.AppendChild(mark); ControlTemplate template = new ControlTemplate(typeof(CheckBox)) { VisualTree = root }; Trigger on = new Trigger { Property = ToggleButton.IsCheckedProperty, Value = true }; on.Setters.Add(new Setter(System.Windows.Controls.Border.BackgroundProperty, new SolidColorBrush(Color.FromRgb(24, 112, 224)), "CheckBoxSquare")); on.Setters.Add(new Setter(System.Windows.Controls.Border.BorderBrushProperty, new SolidColorBrush(Color.FromRgb(24, 112, 224)), "CheckBoxSquare")); on.Setters.Add(new Setter(UIElement.VisibilityProperty, Visibility.Visible, "CheckMark")); template.Triggers.Add(on); style.Setters.Add(new Setter(Control.TemplateProperty, template)); return style; }
